CREATE TABLE truss.runtime_catalog_rebind_transition (transition_id bigint PRIMARY KEY DEFAULT nextval('truss.runtime_object_transition_seq'), registration_id uuid NOT NULL REFERENCES truss.catalog_registration_request (registration_id) DEFERRABLE INITIALLY DEFERRED, writer_xid xid8 NOT NULL, actor_oid oid NOT NULL, revision int NOT NULL REFERENCES truss.schema_rev (rev), object_id bigint NOT NULL, type_id int NOT NULL, before_object jsonb NOT NULL, after_object jsonb NOT NULL, after_keys jsonb NOT NULL, journal jsonb NOT NULL, effects jsonb NOT NULL, UNIQUE (registration_id, object_id, type_id), CHECK (jsonb_typeof(journal) = 'array' AND jsonb_array_length(journal) > 1), CHECK (jsonb_typeof(effects) = 'array' AND jsonb_array_length(effects) > 0)); CREATE INDEX runtime_catalog_rebind_owner ON truss.runtime_catalog_rebind_transition USING btree (object_id, type_id, transition_id DESC); CREATE TRIGGER runtime_catalog_rebind_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON truss.runtime_catalog_rebind_transition EXECUTE FUNCTION truss.catalog_immutable(); REVOKE ALL ON truss.runtime_catalog_rebind_transition FROM public